python3 - <<'PY'
from PIL import Image
im=Image.open('/home/robot/captures/top_001.png').convert('L')
w,h=im.size
# brightness stats
hist=im.histogram()
# print ranges
for i in range(0,256,16):
    print(i, sum(hist[i:i+16]))
# threshold for bright areas
for th in [60,80,100,120,150,200]:
    pix=im.load()
    xs=[]; ys=[]
    for y in range(h):
        for x in range(w):
            if pix[x,y]>th:
                xs.append(x); ys.append(y)
    if xs:
        print('th',th,'bbox',min(xs),min(ys),max(xs),max(ys),'count',len(xs))
PY

